import { useState } from "react";

import AdminB from "./AdminB";
import AdminS from "./AdminS";
import AdminP from "./AdminP";
import AdminU from "./AdminU";
import AdminUsers from "./AdminUsers";
import UserInfo from "./UserInfo";

import "./styles/Admin.css";

function AppAdmin() {
  const [currentPage, setCurrentPage] = useState("login");
  const [currentUser, setCurrentUser] = useState(null);
  const [previousPage, setPreviousPage] = useState(null);

  const usersData = {
    proceso: {
      name: "Jesús Alejandro Espinosa",
      role: "Administrador de procesos administrativos",
      email: "edef@gmail.com",
      password: "********",
      username: "proceso",
    },
    ubicacion: {
      name: "María García López",
      role: "Administrador de ubicaciones",
      email: "maria.garcia@gmail.com",
      password: "********",
      username: "ubicacion",
    },
    super: {
      name: "Carlos Rodríguez Martínez",
      role: "Super Administrador",
      email: "carlos.rodriguez@gmail.com",
      password: "********",
      username: "super",
    },
  };

  const [processes, setProcesses] = useState([
    { id: 1, name: "Kardex", description: "Consulta de Kardex", requirements: "Credencial, Pago", time: "15 minutos" },
    { id: 2, name: "Constancia", description: "Solicitud de constancia", requirements: "Credencial", time: "10 minutos" },
  ]);

  const [locations, setLocations] = useState({
    buildings: [
      { id: 1, name: "Edificio A", location: "Campus Principal", capacity: "500" },
      { id: 2, name: "Edificio B", location: "Campus Principal", capacity: "300" },
    ],
    classrooms: [
      { id: 1, name: "Aula 101", building: "Edificio A", capacity: "40" },
      { id: 2, name: "Aula 102", building: "Edificio A", capacity: "35" },
    ],
    laboratories: [
      { id: 1, name: "Lab Informática", building: "Edificio B", equipment: "Computadoras" },
      { id: 2, name: "Lab Química", building: "Edificio B", equipment: "Reactivos" },
    ],
  });

  // --- funciones de control ---
  const handleLogin = (username) => {
    const userType = Object.keys(usersData).find((key) => username.toLowerCase().includes(key));
    if (userType && usersData[userType]) {
      setCurrentUser(usersData[userType]);
      if (userType === "super") setCurrentPage("adminS");
      else if (userType === "ubicacion") setCurrentPage("adminU");
      else setCurrentPage("adminP");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentPage("login");
    setPreviousPage(null);
  };

  const handleAddProcess = (newProcess) => {
    setProcesses([...processes, { ...newProcess, id: processes.length + 1 }]);
    setCurrentPage(previousPage || "adminP");
  };

  const handleDeleteProcess = (id) => {
    setProcesses(processes.filter((p) => p.id !== id));
  };

  const handleEditProcess = (id, updatedProcess) => {
    setProcesses(processes.map((p) => (p.id === id ? updatedProcess : p)));
  };

  const handleDeleteUser = (username) => console.log("Eliminar usuario:", username);
  const handleEditUser = (username) => console.log("Editar usuario:", username);

  return (
    <div className="app">
      {currentPage === "login" && <AdminB onLogin={handleLogin} />}
      {currentPage === "adminS" && currentUser && (
        <AdminS
          users={Object.values(usersData)}
          user={currentUser}
          onViewInfo={() => setCurrentPage("userInfo")}
          onLogout={handleLogout}
          onDeleteUser={handleDeleteUser}
          onEditUser={handleEditUser}
          onBack={() => setCurrentPage("login")}
          onManageProcesses={() => {
            setPreviousPage("adminS");
            setCurrentPage("adminP");
          }}
          onManageLocations={() => {
            setPreviousPage("adminS");
            setCurrentPage("adminU");
          }}
          onManageUsers={() => {
            setPreviousPage("adminS");
            setCurrentPage("adminUsers");
          }}
        />
      )}
      {currentPage === "adminP" && currentUser && (
        <AdminP
          processes={processes}
          user={currentUser}
          onViewInfo={() => setCurrentPage("userInfo")}
          onAddProcess={handleAddProcess}
          onLogout={handleLogout}
          onDeleteProcess={handleDeleteProcess}
          onEditProcess={handleEditProcess}
          onBack={() => setCurrentPage(previousPage || "login")}
          showBackButton={previousPage === "adminS"}
        />
      )}
      {currentPage === "adminU" && currentUser && (
        <AdminU
          locations={locations}
          user={currentUser}
          onViewInfo={() => setCurrentPage("userInfo")}
          onLogout={handleLogout}
          onBack={() => setCurrentPage(previousPage || "login")}
          showBackButton={previousPage === "adminS"}
        />
      )}
      {currentPage === "adminUsers" && currentUser && (
        <AdminUsers
          users={Object.values(usersData)}
          user={currentUser}
          onViewInfo={() => setCurrentPage("userInfo")}
          onLogout={handleLogout}
          onBack={() => setCurrentPage(previousPage || "login")}
        />
      )}
      {currentPage === "userInfo" && currentUser && (
        <UserInfo
          user={currentUser}
          onBack={() =>
            setCurrentPage(
              previousPage ||
                (currentUser.username === "super"
                  ? "adminS"
                  : currentUser.username === "ubicacion"
                  ? "adminU"
                  : "adminP")
            )
          }
          onLogout={handleLogout}
        />
      )}
    </div>
  );
}

export default AppAdmin;
